/* @lc app=leetcode id=2973 lang=kotlin */ class Solution { fun placedCoins(edges: Array<IntArray>, cost: IntArray): LongArray = cost.size.let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> IntArray(n).let { sz -> Array<List<Int>>(n) { emptyList() }.let { big -> Array<List<Int>>(n) { emptyList() }.let { small -> order.forEach { v -> g[v].orEmpty().filter { par[it] == v && it != 0 }.let { ch -> (1 + ch.sumOf { sz[it] }).let { sz[v] = it }.also { big[v] = (ch.flatMap { big[it] } + cost[v]).sortedDescending().take(3) }.also { small[v] = (ch.flatMap { small[it] } + cost[v]).sorted().take(2) } } }.let { LongArray(n) { v -> if (sz[v] < 3) 1L else maxOf(0L, big[v][0].toLong() * big[v][1] * big[v][2], small[v][0].toLong() * small[v][1] * big[v][0]) } } } } } } } } } }